    [266433] = "Ящики та кошики, з яких випадали напівупаковані речі. Хто б це не зібрав, той поспішно пішов.",
    [267001] = "Проста скляна пляшечка для збору чистої води.",
    [267086] = "М'який.",
    [267178] = "Прямо до останньої пащі!",
    [267244] = "До: Фредді, Від: Елеонори",
    [267256] = "Колода з офіційною печаткою Фархолда, знайдена у культиста Сутінкового Молота.",
    [267341] = "Ніколи не ставайте між фурболгом та його улюбленими ласощами.",
    [268109] = "Навчає, як викликати цього супутника.",
    [268298] = "Ця суміш очищає уражених тварин від скверни.",
    [268336] = "Ця покращена суміш очищає уражених тварин від псування скверни.",
    [268415] = "Вирощуйте в теплиці або комбінуйте насіннєвий гібридизатор у таборі, щоб розкрити його повний потенціал.",
    [268416] = "Вирощуйте в теплиці або комбінуйте насіннєвий гібридизатор у таборі, щоб розкрити його повний потенціал.",
    [268417] = "Вирощуйте в теплиці або комбінуйте насіннєвий гібридизатор у таборі, щоб розкрити його повний потенціал.",
    [268418] = "Вирощуйте в теплиці або комбінуйте насіннєвий гібридизатор у таборі, щоб розкрити його повний потенціал.",
    [268423] = "Дивно довго.",
    [268502] = "Навчає, як викликати цього супутника.",
    [268503] = "Навчає, як викликати цього супутника.",
    [268647] = "Вузлована суміш різноманітних нутрощів.",
    [268664] = "Пахне смертю. І на смак теж.",
    [268677] = "Шкіра пахне дощем та бджолиним воском.",
    [268813] = "Від купи долинає їдкий запах сірки, який при випадковому вдиханні викликає печіння в носі та горлі. Він теплий на дотик і м’яко світиться прихованою енергією Скверни.",
    [268814] = "Шматочки чогось, що не зовсім розчинилося...",
    [268815] = "Занадто малий, щоб його розпізнати, але достатньо гострий, щоб залишити неприємний поріз.",
    [268967] = "Це грубе намисто трохи нагадує... ведмедя? Оленя? Орла? Ведмедя-стігля?",
    [268990] = "Цей бездоганний кристал тихо гуде у ваших руках і випромінює слабке світло. Попелястий відтінок ніби покриває його тьмяну поверхню, а прожилки попелу створюють всередині складний візерунок.",
    [268998] = "Цей спис прикрашений повітряними дрібничками та ледь чутно гуде від сили неба.",
    [269008] = "Густий і майже желеподібний за консистенцією, цей сік здається таким же їдким, як і густим.",
    [269011] = "Сік залишає болісний опік на будь-якій шкірі, з якою він контактує.",
    [269013] = "Ця суміш змінює псування у тварин, уражених енергіями скверни.",
    [269233] = "Коли ви тримаєте цей кристал, здається, ніби щось корчиться всередині нього.",
    [269247] = "Душа ліча більше не ворушиться всередині.",
    [269326] = "НЕ ВИКОРИСТОВУВАЛИ",
    [269327] = "Умбрінот",
    [269671] = "Навчає, як викликати цього їздова тваринаа.",
    [269673] = "Навчає, як викликати цього їздова тваринаа.",
    [269678] = "Навчає, як викликати цього їздова тваринаа.",
    [269681] = "Навчає, як викликати цього їздова тваринаа.",
