    [269758] = "Колись я стану справжнім шедевром...",
    [269759] = "Колись я стану справжнім шедевром...",
    [269774] = "На склі липне дуже в'язкий і злегка світиться зелений тил.",
    [269777] = "Невеликий пристрій, щоб швидко викликати іскри та полум'я одним рухом пальця.",
    [269810] = "Обери свою частину!",
    [269830] = "Навчає, як викликати цього супутника.",
    [269901] = "Навчає, як створити Пристрій для розгортання прапора Кентавра.",
    [269903] = "Навчає, як створити педаль у формі копита.",
    [270151] = "Накази від лейтенанта Бенедикта з Тірагардського замку.",
    [270298] = "Сила породжує силу. Це лише мала частина того, що чекає на тебе...",
    [270308] = "Доля в крові",
    [270309] = "Перший Припливоносець",
    [270310] = "Тріснуті та прокляті",
    [270311] = "Лоа Загублених",
    [270312] = "Зведений список перекладених творів з табличок у загубленому місті тролів І'лалай, Затонулому Місті.",
    [270313] = "Зведений список дій з табличок у загубленому місті тролів І'лалай, Затонулому Місті, транскрибований сучасною зандальською мовою Кін'вілаєм.",
    [270332] = "Напрочуд свіжо.",
    [270333] = "Ці артефакти гудуть прихованою енергією та, здається, притягують різні суперечливі магічні сили в Затопленому Місті.",
    [270436] = "Знак вірності від паладинів фортеці Бандаріон. - Даніта Морр",
    [270865] = "Фрагментовані залишки конструкції, що заломлюють світло, немов калейдоскоп.",
    [270866] = "Фрагментовані залишки конструкції, що заломлюють світло, немов калейдоскоп.",
    [270868] = "Відкрито для бізнесу!",
    [270870] = "Відкрито для бізнесу!",
    [270887] = "Містить інформацію та інструкції щодо того, як отримати власну іграшку-вивіску Орківського ремесла.",
    [270888] = "Містить інформацію та інструкції щодо того, як отримати власну іграшку-знак гномьої ремесленості.",
    [270901] = "Плетена трава у формі серця.",
    [271350] = "Проклята душа, що кличе до жертви.",
    [271647] = "Заглядання всередину може призвести до неприємних відкриттів.",
    [271648] = "Як новий.",
    [271654] = "Це робить його вдвічі отруйнішим, чи вдвічі?",
    [271721] = "Це виконує роботу.",
    [271745] = "Мапа з гномськими каракулями та підкресленим X.",
    [271770] = "Стандартний комплект з усіма інструментами, необхідними для дослідження та категоризації нещодавно досліджених територій.",
    [271771] = "Коштовний камінь, прохолодний на дотик і ніжно гуде. Дивно, але крізь нього, здається, не пробивається світло.",
    [271870] = "Марний шматок вугілля.",
    [271880] = "Від дивного різьблення виходить загрозливе сяйво.",
    [271894] = "Коштовний камінь, гарячий на дотик і тихо гуде. Здається, що він випромінює невелику кількість світла, майже як мерехтіння вогню.",
    [271898] = "Самоцвіт, який тихо гуде та ніби випромінює статичний заряд. Сам по собі він випромінює крихітну кількість світла, і невеликі спалахи можна побачити прямо під поверхнею, ніби всередині застрягла крихітна буря.",
    [271902] = "Коштовний камінь, який ніби виділяє ледь помітні випари та тихо гуде. Він трохи горить, щоб триматися в руці, але коли його падає на землю, навколо нього проростає нова трава.",
    [271912] = "Коштовний камінь, який ніби збирає конденсат на поверхні, роблячи його постійно вологим і тихо гуде. Якщо повернути його на світлі, виглядає так, ніби всередині самого кристала затримана вода.",
    [271972] = "Ця сторінка все ще мокра і сильно смердить.",
    [271994] = "Голосно дзвенить від звуку золота та корисних товарів усередині.",
    [272000] = "Тільки гоблін міг би це полюбити, але їм би це ДУЖЕ сподобалося.",
    [272001] = "Ооо! Блискуче.",
    [272011] = "Блискавковідвід гуде від природної енергії, незважаючи на завдані йому пошкодження.",
    [272014] = "Солідна гномська майстерність.",
    [272015] = "Блискучий!",
    [272016] = "Еврика!",
    [272017] = "Документ драконівською мовою з печаткою Нефаріона",
    [272018] = "Документ драконівською мовою з печаткою генерала Драккісата",
    [272019] = "Детальний контракт, що визначав придане та права на спадщину для шлюбу Даграна Тауріссана та Мойри Бронзобородої.",
    [272020] = "Насіння рослини, настояної на скверні, що світиться демонічною енергією.",
    [272021] = "Розбитий кулон зі зламаною печаткою Шен'драласа.",
    [272022] = "Мізинець людожера, інкрустований легендарним дреенським діамантом з земляного каменю",
    [272023] = "Записи про зарахування до Схоломансу під час великої чуми",
    [272024] = "Детальні накази про відвантаження зерна, написані бароном Рівендаром під час великої чуми",
    [272025] = "Листування Саїдана Датрохана до та під час третьої війни",
    [272026] = "Кристалізована сльоза великого дракона Ізери.",
    [272027] = "Знак служби палаючому легіону, в ім'я сатира Ксавія.",
    [272028] = "Камінь, позначений символом титана Фрейї",
    [272124] = "Збірка перекладених творів Лоремайстра Діббса, що розповідає історію про загублене місто тролів, І'лалай, Затоплене Місто.",
    [272151] = "Цей пом'ятий та пошкоджений ящик виглядає так, ніби він буквально впав із задньої частини дирижабля.",
    [272313] = "Руків'я неймовірно стародавнє, але метал, що проглядає крізь пил і бруд, досі яскраво сяє. Ця зброя явно була шедевром, перш ніж її зламали.",
    [272314] = "Рідина всередині флакона ніби сильно вирує та прилипає до скла таким чином, що свідчить про певну еластичність.",
    [272977] = "Надзвичайно добре збережений, цей дивний виріб, мабуть, був викуваний зі сплаву, стійкого до корозії.",
    [273002] = "І руни, і рукопис танцюють по поверхні сторінки, немов павуки. Щось у цій книзі здається зловісним і неприродним.",
    [273008] = "Цей слиз звивається у ваших руках і залишає сліди опіків на відкритій шкірі. Здається, він має власний розум.",
    [273050] = "Їх можна зібрати для фурболгів Чорнощів в Урсолані, щоб заслужити їхню довіру.",
    [273085] = "Навчить, як розмістити ферментер на кемпінгу.",
    [273086] = "Навчає, як розмістити ковадло на кемпінгу.",
    [273087] = "Навчить, як розкласти багаття для підмайстрів у кемпінгу.",
    [273092] = "Навчає, як розмістити ремонтного робота на кемпінгу.",
    [273096] = "Навчить, як розмістити стійку для засмаги на кемпінгу.",
    [273097] = "Навчить, як розмістити альпінарій на кемпінгу.",
    [273098] = "Навчає, як розмістити польового гіда на кемпінгу.",
    [273099] = "Навчить, як розмістити прядку на кемпінгу.",
    [273101] = "Навчить, як розвести багаття для досвідчених кемпінгу.",
    [273102] = "Навчає, як розмістити «Бенкет Печива» на кемпінгу.",
