    [273321] = "Містить випадковий асортимент професійних матеріалів для ремісників.",
    [273642] = "Всередині стрічки вигравірувано ім'я. Хоча його важко прочитати, ініціали «Т» та «Бель» розбірливі.",
    [273658] = "У складках шат Виводкової Матері захована записка.",
    [273659] = "У листі згадується «Пакт» та «Дикий Король»... що це може означати?",
    [273772] = "Документ закритий малиновою восковою печаткою.",
    [273798] = "Всередині стрічки вигравірувано ім'я. Хоча його важко прочитати, ініціали «Т» та «Бель» розбірливі.",
    [273799] = "Перстень загиблого солдата, Томас Белль.",
    [273845] = "Цю ампулу ретельно вирізьбили з одного з кристалів попелу феї поблизу, що надає їй блідо-зеленуватого відтінку. Коли світло потрапляє на неї, здається, що в кристалічних стінках, що ледь помітно мерехтять енергією феї, застряг попіл.",
